56	    isArchived,
57	    readonly,
58	    isInMemoDetailPage,
59	    commentAmount,
60	    createTime,
61	    updateTime,
62	    displayTime,
63	    isDisplayingUpdatedTime,
64	    relativeTimeFormat,
