1	// Utilities for manipulating markdown strings using AST parsing
2	// Uses mdast for accurate task detection that properly handles code blocks
3	
4	import type { Heading, ListItem } from "mdast";
5	import { fromMarkdown } from "mdast-util-from-markdown";
6	import { gfmFromMarkdown } from "mdast-util-gfm";
7	import { gfm } from "micromark-extension-gfm";
8	import { visit } from "unist-util-visit";
9	
10	interface TaskInfo {
11	  lineNumber: number;
12	  checked: boolean;
13	}
14	
15	// Extract all task list items from markdown using AST parsing
16	// This correctly ignores task-like patterns inside code blocks
17	function extractTasksFromAst(markdown: string): TaskInfo[] {
18	  const tree = fromMarkdown(markdown, {
19	    extensions: [gfm()],
20	    mdastExtensions: [gfmFromMarkdown()],
21	  });
22	
23	  const tasks: TaskInfo[] = [];
24	
25	  visit(tree, "listItem", (node: ListItem) => {
26	    // Only process actual task list items (those with a checkbox)
27	    if (typeof node.checked === "boolean" && node.position?.start.line) {
28	      tasks.push({
29	        lineNumber: node.position.start.line - 1, // Convert to 0-based
30	        checked: node.checked,
31	      });
32	    }
33	  });
34	
35	  return tasks;
36	}
37	
38	export function toggleTaskAtLine(markdown: string, lineNumber: number, checked: boolean): string {
39	  const lines = markdown.split("\n");
40	
41	  if (lineNumber < 0 || lineNumber >= lines.length) {
42	    return markdown;
43	  }
44	
45	  const line = lines[lineNumber];
46	
47	  // Match task list patterns: - [ ], - [x], - [X], etc.
48	  const taskPattern = /^(\s*[-*+]\s+)\[([ xX])\](\s+.*)$/;
49	  const match = line.match(taskPattern);
50	
51	  if (!match) {
52	    return markdown;
53	  }
54	
55	  const [, prefix, , suffix] = match;
56	  const newCheckmark = checked ? "x" : " ";
57	  lines[lineNumber] = `${prefix}[${newCheckmark}]${suffix}`;
58	
59	  return lines.join("\n");
60	}
61	
62	export function toggleTaskAtIndex(markdown: string, taskIndex: number, checked: boolean): string {
63	  const tasks = extractTasksFromAst(markdown);
64	
65	  if (taskIndex < 0 || taskIndex >= tasks.length) {
66	    return markdown;
67	  }
68	
69	  const task = tasks[taskIndex];
70	  return toggleTaskAtLine(markdown, task.lineNumber, checked);
71	}
72	
73	export function countTasks(markdown: string): {
74	  total: number;
75	  completed: number;
76	  incomplete: number;
77	} {
78	  const tasks = extractTasksFromAst(markdown);
79	
80	  const total = tasks.length;
81	  const completed = tasks.filter((t) => t.checked).length;
82	
83	  return {
84	    total,
85	    completed,
86	    incomplete: total - completed,
87	  };
88	}
89	
90	export function getTaskLineNumber(markdown: string, taskIndex: number): number {
91	  const tasks = extractTasksFromAst(markdown);
92	
93	  if (taskIndex < 0 || taskIndex >= tasks.length) {
94	    return -1;
95	  }
96	
97	  return tasks[taskIndex].lineNumber;
98	}
