1	import type { MemoRelation } from "@/types/proto/api/v1/memo_service_pb";
2	import { MemoRelation_Type } from "@/types/proto/api/v1/memo_service_pb";
3	
4	export type RelationDirection = "referencing" | "referenced";
5	
6	export const isReferenceRelation = (relation: MemoRelation): boolean => relation.type === MemoRelation_Type.REFERENCE;
7	
8	export const getEditorReferenceRelations = (relations: MemoRelation[], memoName?: string): MemoRelation[] => {
9	  return relations.filter(
10	    (relation) => isReferenceRelation(relation) && (!memoName || !relation.memo?.name || relation.memo.name === memoName),
11	  );
12	};
