14	export const getRelationBuckets = (relations: MemoRelation[], currentMemoName?: string) => {
15	  return relations.reduce(
16	    (groups, relation) => {
17	      if (!isReferenceRelation(relation)) {
18	        return groups;
19	      }
20	
21	      if (relation.memo?.name === currentMemoName && relation.relatedMemo?.name !== currentMemoName) {
22	        groups.referencing.push(relation);
23	      } else if (relation.memo?.name !== currentMemoName && relation.relatedMemo?.name === currentMemoName) {
24	        groups.referenced.push(relation);
25	      }
26	
27	      return groups;
28	    },
29	    {
30	      referencing: [] as MemoRelation[],
31	      referenced: [] as MemoRelation[],
32	    },
33	  );
34	};
35	
36	export const getRelationMemo = (relation: MemoRelation, direction: RelationDirection) => {
37	  return direction === "referencing" ? relation.relatedMemo : relation.memo;
38	};
39	
40	export const getRelationMemoName = (relation: MemoRelation, direction: RelationDirection): string => {
41	  return getRelationMemo(relation, direction)?.name ?? "";
42	};
