52	export function buildAttachmentVisualItems(attachments: Attachment[]): AttachmentVisualItem[] {
53	  const attachmentsByGroup = new Map<string, Attachment[]>();
54	  for (const attachment of attachments) {
55	    const groupId = getAttachmentMotionGroupId(attachment);
56	    if (!groupId) {
57	      continue;
58	    }
59	    const group = attachmentsByGroup.get(groupId) ?? [];
60	    group.push(attachment);
61	    attachmentsByGroup.set(groupId, group);
62	  }
63	
64	  const consumedGroups = new Set<string>();
65	  const items: AttachmentVisualItem[] = [];
66	
67	  for (const attachment of attachments) {
68	    if (isAndroidMotionContainer(attachment)) {
69	      items.push(buildAndroidMotionItem(attachment));
70	      continue;
71	    }
72	
73	    const groupId = getAttachmentMotionGroupId(attachment);
74	    if (!groupId || consumedGroups.has(groupId)) {
75	      if (!groupId) {
76	        items.push(buildSingleAttachmentItem(attachment));
77	      }
78	      continue;
79	    }
80	
81	    const group = attachmentsByGroup.get(groupId) ?? [];
82	    const still = group.find(isAppleLivePhotoStill);
83	    const video = group.find(isAppleLivePhotoVideo);
84	    if (still && video && group.length === 2) {
85	      items.push(buildAppleMotionItem(still, video));
86	      consumedGroups.add(groupId);
87	      continue;
88	    }
89	
90	    items.push(buildSingleAttachmentItem(attachment));
91	    consumedGroups.add(groupId);
92	    for (const member of group) {
93	      if (member.name === attachment.name) {
94	        continue;
95	      }
96	      items.push(buildSingleAttachmentItem(member));
97	    }
98	  }
99	
100	  return dedupeVisualItems(items);
101	}
