104	  const visualAttachments = attachments.filter(
105	    (attachment) =>
106	      getAttachmentType(attachment) === "image/*" || getAttachmentType(attachment) === "video/*" || isMotionAttachment(attachment),
107	  );
108	  const visualNames = new Set(visualAttachments.map((attachment) => attachment.name));
109	  const visualCount = buildAttachmentVisualItems(visualAttachments).length;
110	  const nonVisualCount = attachments.filter((attachment) => !visualNames.has(attachment.name)).length;
111	  return visualCount + nonVisualCount;
112	}
113	
114	function buildSingleAttachmentItem(attachment: Attachment): AttachmentVisualItem {
115	  const attachmentType = getAttachmentType(attachment);
116	  const sourceUrl = getAttachmentUrl(attachment);
117	  const posterUrl = attachmentType === "image/*" ? getAttachmentThumbnailUrl(attachment) : sourceUrl;
118	  const previewKind = attachmentType === "video/*" ? "video" : "image";
119	
120	  return {
121	    id: attachment.name,
122	    kind: attachmentType === "video/*" ? "video" : "image",
123	    filename: attachment.filename,
124	    posterUrl,
125	    sourceUrl,
126	    attachmentNames: [attachment.name],
127	    attachments: [attachment],
128	    previewItem: {
129	      id: attachment.name,
130	      kind: previewKind,
131	      sourceUrl,
132	      posterUrl,
133	      filename: attachment.filename,
134	    },
135	    mimeType: attachment.type,
136	  };
137	}
138	
139	function buildAppleMotionItem(still: Attachment, video: Attachment): AttachmentVisualItem {
140	  const sourceUrl = getAttachmentUrl(video);
141	  const posterUrl = getAttachmentThumbnailUrl(still);
142	
143	  return {
144	    id: getAttachmentMotionGroupId(still) ?? still.name,
145	    kind: "motion",
146	    filename: still.filename,
147	    posterUrl,
148	    sourceUrl,
149	    attachmentNames: [still.name, video.name],
150	    attachments: [still, video],
151	    previewItem: {
152	      id: getAttachmentMotionGroupId(still) ?? still.name,
153	      kind: "motion",
154	      posterUrl,
155	      motionUrl: sourceUrl,
156	      filename: still.filename,
157	    },
158	    mimeType: still.type,
159	  };
160	}
161	
162	function buildAndroidMotionItem(attachment: Attachment): AttachmentVisualItem {
163	  return {
164	    id: attachment.name,
165	    kind: "motion",
166	    filename: attachment.filename,
167	    posterUrl: getAttachmentThumbnailUrl(attachment),
168	    sourceUrl: getAttachmentMotionClipUrl(attachment),
169	    attachmentNames: [attachment.name],
170	    attachments: [attachment],
171	    previewItem: {
172	      id: attachment.name,
173	      kind: "motion",
174	      motionUrl: getAttachmentMotionClipUrl(attachment),
175	      posterUrl: getAttachmentThumbnailUrl(attachment),
176	      filename: attachment.filename,
177	      presentationTimestampUs: attachment.motionMedia?.presentationTimestampUs,
178	    },
179	    mimeType: attachment.type,
180	  };
181	}
182	
183	function dedupeVisualItems(items: AttachmentVisualItem[]): AttachmentVisualItem[] {
184	  const seen = new Set<string>();
185	  return items.filter((item) => {
186	    if (seen.has(item.id)) {
187	      return false;
188	    }
189	    seen.add(item.id);
190	    return true;
191	  });
192	}
