1	import { Attachment, MotionMediaFamily, MotionMediaRole } from "@/types/proto/api/v1/attachment_service_pb";
2	
3	export const getAttachmentUrl = (attachment: Attachment) => {
4	  if (attachment.externalLink) {
5	    return attachment.externalLink;
6	  }
7	
8	  return `${window.location.origin}/file/${attachment.name}/${attachment.filename}`;
9	};
10	
11	export const getAttachmentThumbnailUrl = (attachment: Attachment) => {
12	  return `${window.location.origin}/file/${attachment.name}/${attachment.filename}?thumbnail=true`;
13	};
14	
15	export const getAttachmentMotionClipUrl = (attachment: Attachment) => {
16	  return `${window.location.origin}/file/${attachment.name}/${attachment.filename}?motion=true`;
17	};
18	
19	export const getAttachmentType = (attachment: Attachment) => {
20	  if (isImage(attachment.type)) {
21	    return "image/*";
22	  } else if (attachment.type.startsWith("video")) {
23	    return "video/*";
24	  } else if (attachment.type.startsWith("audio") && !isMidiFile(attachment.type)) {
25	    return "audio/*";
26	  } else if (attachment.type.startsWith("text")) {
27	    return "text/*";
28	  } else if (attachment.type.startsWith("application/epub+zip")) {
29	    return "application/epub+zip";
30	  } else if (attachment.type.startsWith("application/pdf")) {
31	    return "application/pdf";
32	  } else if (attachment.type.includes("word")) {
33	    return "application/msword";
34	  } else if (attachment.type.includes("excel")) {
35	    return "application/msexcel";
36	  } else if (attachment.type.startsWith("application/zip")) {
37	    return "application/zip";
38	  } else if (attachment.type.startsWith("application/x-java-archive")) {
39	    return "application/x-java-archive";
40	  } else {
41	    return "application/octet-stream";
42	  }
43	};
44	
45	// isImage returns true if the given mime type is an image.
46	export const isImage = (t: string) => {
47	  // Don't show PSDs as images.
48	  return t.startsWith("image/") && !isPSD(t);
49	};
50	
51	// isMidiFile returns true if the given mime type is a MIDI file.
52	export const isMidiFile = (mimeType: string): boolean => {
53	  return mimeType === "audio/midi" || mimeType === "audio/mid" || mimeType === "audio/x-midi" || mimeType === "application/x-midi";
54	};
55	
56	const isPSD = (t: string) => {
57	  return t === "image/vnd.adobe.photoshop" || t === "image/x-photoshop" || t === "image/photoshop";
58	};
59	
60	export const getAttachmentMotionGroupId = (attachment: Attachment): string | undefined => {
61	  return attachment.motionMedia?.groupId || undefined;
62	};
63	
64	export const isAppleLivePhotoStill = (attachment: Attachment): boolean =>
65	  attachment.motionMedia?.family === MotionMediaFamily.APPLE_LIVE_PHOTO && attachment.motionMedia.role === MotionMediaRole.STILL;
66	
67	export const isAppleLivePhotoVideo = (attachment: Attachment): boolean =>
68	  attachment.motionMedia?.family === MotionMediaFamily.APPLE_LIVE_PHOTO && attachment.motionMedia.role === MotionMediaRole.VIDEO;
69	
70	export const isAndroidMotionContainer = (attachment: Attachment): boolean =>
71	  attachment.motionMedia?.family === MotionMediaFamily.ANDROID_MOTION_PHOTO &&
72	  attachment.motionMedia.role === MotionMediaRole.CONTAINER &&
73	  attachment.motionMedia.hasEmbeddedVideo;
74	
75	export const isMotionAttachment = (attachment: Attachment): boolean =>
76	  isAppleLivePhotoStill(attachment) || isAppleLivePhotoVideo(attachment) || isAndroidMotionContainer(attachment);
